SEED_DATA: list[dict] = [
    # ─────────────────────── 八字 bazi ───────────────────────
    # 天干五行
    {"module": "bazi", "category": "天干五行", "keyword": "甲", "content": "甲木：阳木，参天大树，主仁，代表成长、直率、进取。得令旺相则事业有担当；失令太弱宜借印生扶。", "source": "渊海子平"},
    {"module": "bazi", "category": "天干五行", "keyword": "乙", "content": "乙木：阴木，花草藤蔓，主柔韧、亲和、适应力强。喜水滋养，忌金克伐过重。", "source": "渊海子平"},
    {"module": "bazi", "category": "天干五行", "keyword": "丙", "content": "丙火：阳火，太阳之火，主礼、热情外向、光明磊落。旺则耀眼，过旺则燥急冲动。", "source": "渊海子平"},
    {"module": "bazi", "category": "天干五行", "keyword": "丁", "content": "丁火：阴火，灯烛之火，主智慧、细腻、文艺气质。喜木生扶，忌水克灭。", "source": "渊海子平"},
    {"module": "bazi", "category": "天干五行", "keyword": "戊", "content": "戊土：阳土，高山厚土，主信、稳重、承载力强。旺则厚实可依，过旺则固执守旧。", "source": "渊海子平"},
    {"module": "bazi", "category": "天干五行", "keyword": "己", "content": "己土：阴土，田园湿土，主包容、务实、细心。喜火暖，忌水泛滥成灾。", "source": "渊海子平"},
    {"module": "bazi", "category": "天干五行", "keyword": "庚", "content": "庚金：阳金，斧钺利器，主义、刚毅果断、执行力强。得火锻炼则成大器，过旺伤身。", "source": "渊海子平"},
    {"module": "bazi", "category": "天干五行", "keyword": "辛", "content": "辛金：阴金，珠宝首饰，主精细、审美、洁癖。喜水洗涤，忌火煅炼过甚。", "source": "渊海子平"},
    {"module": "bazi", "category": "天干五行", "keyword": "壬", "content": "壬水：阳水，江海奔流，主智、胸怀广阔、变通灵活。太旺则漂泊无定，宜土堤疏导。", "source": "渊海子平"},
    {"module": "bazi", "category": "天干五行", "keyword": "癸", "content": "癸水：阴水，雨露滋润，主聪慧、内敛、感情细腻。喜金生，忌戊土制克过重。", "source": "渊海子平"},
    # 地支
    {"module": "bazi", "category": "地支", "keyword": "子", "content": "子水：冬月水旺，主智慧、夜行、隐秘。子月生人多聪慧机变，情感丰富。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "丑", "content": "丑土：冬末湿土，蓄藏之力，主勤劳、积累。丑月生人务实稳重，财库深厚。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "寅", "content": "寅木：春初阳木，虎气刚健，主进取、开创、领导力。寅月生人精力充沛，勇于担当。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "卯", "content": "卯木：春旺阴木，桃花之象，主文艺、亲和、人缘好。感情丰富，异性缘佳。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "辰", "content": "辰土：春末水库，龙气蓄势，主宽厚、积聚。辰月生人思维深远，善于谋划。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "巳", "content": "巳火：夏初阴火，主文明、礼仪、热情。巳月生人表达能力强，社交活跃。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "午", "content": "午火：夏旺阳火，主热情奔放、外向自信。午月生人行动力强，容易出名。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "未", "content": "未土：夏末火库，主温柔、艺术气质。未月生人感性细腻，重情重义。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "申", "content": "申金：秋初阳金，主果断、变革。申月生人思维敏捷，善于应变，偏好新事物。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "酉", "content": "酉金：秋旺阴金，主精细、品味。酉月生人审美高，追求完美，适合技艺精进方向。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "戌", "content": "戌土：秋末火库，主忠诚、威严。戌月生人义气深重，做事有始有终。", "source": "渊海子平"},
    {"module": "bazi", "category": "地支", "keyword": "亥", "content": "亥水：冬初阴水，主智慧、深沉。亥月生人内心世界丰富，直觉敏锐，善于研究。", "source": "渊海子平"},
    # 五行旺衰
    {"module": "bazi", "category": "五行旺衰", "keyword": "木旺", "content": "木旺之人：仁慈博爱，行动力强，适合文教、医疗、艺术、林业等方向。木过旺则固执，宜金适度克制以塑形。", "source": "穷通宝鉴"},
    {"module": "bazi", "category": "五行旺衰", "keyword": "火旺", "content": "火旺之人：热情奔放，表现欲强，适合娱乐、销售、管理、能源等行业。火过旺则急躁易怒，宜水克制以平衡。", "source": "穷通宝鉴"},
    {"module": "bazi", "category": "五行旺衰", "keyword": "土旺", "content": "土旺之人：稳重可靠，执行力强，适合地产、农业、仓储、行政等行业。土过旺则固执迟缓，宜木疏土以活化。", "source": "穷通宝鉴"},
    {"module": "bazi", "category": "五行旺衰", "keyword": "金旺", "content": "金旺之人：果断干练，原则性强，适合军警、法律、金融、机械等行业。金过旺则刚愎自用，宜火锻炼以成器。", "source": "穷通宝鉴"},
    {"module": "bazi", "category": "五行旺衰", "keyword": "水旺", "content": "水旺之人：聪明机智，变通灵活，适合科研、贸易、航运、传媒等行业。水过旺则漂泊多变，宜土堤坝以稳定。", "source": "穷通宝鉴"},
    # 命势判断
    {"module": "bazi", "category": "命势判断", "keyword": "吉势偏强", "content": "当前命势偏强，五行有余，精力充沛，适合主动出击、开拓新局面。注意不可过于强势，以免引起反弹。宜借此窗口期大胆推进核心目标。", "source": "穷通宝鉴"},
    {"module": "bazi", "category": "命势判断", "keyword": "平衡中和", "content": "当前命势平衡，五行中和，大事适宜稳步推进。不宜急功近利，宜厚积薄发，在稳健中寻找突破口。人际关系和谐，合作顺畅。", "source": "渊海子平"},
    {"module": "bazi", "category": "命势判断", "keyword": "偏弱待扶", "content": "当前命势偏弱，需要外力扶持与积累。不宜单打独斗，适合借助团队或贵人之力。专注修炼内功，等待时机成熟再出手。", "source": "渊海子平"},
    {"module": "bazi", "category": "命势判断", "keyword": "流年运势", "content": "流年运势分析：看大运与流年天干地支与日主的生克关系。逢印绶年份主学业进步；逢财星旺年主财运亨通；逢官星年主仕途升迁；逢比劫年主竞争加剧，宜守不宜攻。", "source": "渊海子平"},
    # 大运流年
    {"module": "bazi", "category": "大运", "keyword": "行印运", "content": "行印绶大运：学业、资质、贵人缘大增。适合深造学习、考证、拜师求学。母缘、贵人缘强，上级提携机会多。", "source": "渊海子平"},
    {"module": "bazi", "category": "大运", "keyword": "行财运", "content": "行财星大运：财源广进，投资收益显现，事业经营顺畅。注意防范破财风险，勿贪图暴利。父缘、异性缘有变化。", "source": "渊海子平"},
    {"module": "bazi", "category": "大运", "keyword": "行官运", "content": "行官杀大运：仕途升迁机会大增，地位提升。职场竞争激烈，压力增大。需保持规矩，以免惹祸上身。", "source": "渊海子平"},
    {"module": "bazi", "category": "大运", "keyword": "行比劫运", "content": "行比劫大运：竞争加剧，财易被劫。宜与人合作，发挥团队力量。兄弟朋友关系变化多，防人际纠纷。", "source": "渊海子平"},

    # ─────────────────────── 六爻 liuyao ───────────────────────
    {"module": "liuyao", "category": "六亲", "keyword": "父母爻", "content": "父母爻：代表父母、长辈、上司、文书、合同、雨水。父母爻旺相，上司提携有力，文书合同顺利。", "source": "增删卜易"},
    {"module": "liuyao", "category": "六亲", "keyword": "子孙爻", "content": "子孙爻：代表子女、下属、医药、福德。子孙爻旺则身体健康，忧愁消散，祈福有效。问病宜见子孙爻旺。", "source": "增删卜易"},
    {"module": "liuyao", "category": "六亲", "keyword": "官鬼爻", "content": "官鬼爻：代表官非、疾病、鬼神、丈夫（对女方）。官爻旺对男性而言主升职，但也要防官司小人。问病官鬼临日月动爻须注意。", "source": "增删卜易"},
    {"module": "liuyao", "category": "六亲", "keyword": "妻财爻", "content": "妻财爻：代表钱财、妻子、下属、食物。妻财旺则财运亨通，问财卦见财爻旺相持世为佳。", "source": "增删卜易"},
    {"module": "liuyao", "category": "六亲", "keyword": "兄弟爻", "content": "兄弟爻：代表兄弟、朋友、同辈竞争者、耗财之神。兄弟爻旺动则破财、竞争激烈、合伙不利，问财忌见。", "source": "增删卜易"},
    # 世应
    {"module": "liuyao", "category": "世应", "keyword": "世爻旺相", "content": "世爻旺相：问事主动权在己，自身能量充足，结果偏向自己期望。宜主动出击，把握时机。", "source": "增删卜易"},
    {"module": "liuyao", "category": "世应", "keyword": "应爻旺相", "content": "应爻旺相：对方或外部力量强大，需借助外力或顺势而为。问合作、谈判，对方占优势，需让步或等待。", "source": "增删卜易"},
    {"module": "liuyao", "category": "世应", "keyword": "世应相生", "content": "世应相生：双方互利，合作共赢。感情卦见此，情投意合；生意卦见此，合作顺利，互利互惠。", "source": "增删卜易"},
    {"module": "liuyao", "category": "世应", "keyword": "世应相克", "content": "世应相克：双方存在分歧或对抗。应克世则被动、受制；世克应则主动、压制对方。感情有矛盾，生意有竞争。", "source": "增删卜易"},
    # 动爻变卦
    {"module": "liuyao", "category": "动爻", "keyword": "无动爻", "content": "无动爻（静卦）：事情处于静止或胶着状态，短期内不会有大变化。当前宜守不宜攻，静待时机。", "source": "增删卜易"},
    {"module": "liuyao", "category": "动爻", "keyword": "一爻动", "content": "一爻动：事情有单一的变化关键点，问题焦点集中。看动爻所代表的六亲即可知变化方向。", "source": "增删卜易"},
    {"module": "liuyao", "category": "动爻", "keyword": "多爻动", "content": "多爻动（三爻以上）：事情变化复杂多端，局面混乱，难以把握。宜稳健保守，不宜冒险。以静制动为上策。", "source": "增删卜易"},
    # 卦象吉凶
    {"module": "liuyao", "category": "吉凶判断", "keyword": "大吉", "content": "卦象大吉：世爻旺相持世，用神旺动生合世爻，无忌神克害，事成可期。把握当前时机，积极推进。", "source": "增删卜易"},
    {"module": "liuyao", "category": "吉凶判断", "keyword": "小吉", "content": "卦象小吉：用神有气但力量有限，需要时间积累或外力辅助，结果偏好但过程曲折。耐心等待，循序渐进。", "source": "增删卜易"},
    {"module": "liuyao", "category": "吉凶判断", "keyword": "平", "content": "卦象平平：用神不旺不衰，事情可成可败，取决于自身努力和外部机缘。中规中矩，不宜冒进。", "source": "增删卜易"},
    {"module": "liuyao", "category": "吉凶判断", "keyword": "凶", "content": "卦象偏凶：忌神旺动克世或用神，事情阻碍较多。宜暂缓、另谋他策，或待时机转变再出手。", "source": "增删卜易"},

    # ─────────────────────── 姓名学 name_wuge ───────────────────────
    {"module": "name_wuge", "category": "五格解析", "keyword": "天格", "content": "天格：由姓氏笔画决定（单姓加1，复姓不加），代表先天祖业、父系遗传，与早年运势及长辈关系密切。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "五格解析", "keyword": "人格", "content": "人格：姓名的核心数理，由姓的最后一字与名的第一字笔画之和构成。代表性格、才能与中年运势，是五格中最重要的格位。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "五格解析", "keyword": "地格", "content": "地格：名字笔画之和（双名则两字相加，单名加1），代表家庭、感情与晚年运势，也关联子女缘。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "五格解析", "keyword": "外格", "content": "外格：天格+地格-人格（或特定算法），代表社交、人际关系与外部环境。外格好则人缘佳，处世圆融。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "五格解析", "keyword": "总格", "content": "总格：姓名所有笔画之和，代表整体人生运势与晚年总结。总格吉利，则人生后期顺遂，晚年安康。", "source": "姓名学五格剖象法"},
    # 数理吉凶
    {"module": "name_wuge", "category": "数理吉凶", "keyword": "大吉数", "content": "大吉数（1、3、5、6、8、11、13、15、16、21、23、24、25、29、31、32、35、37、41、45、47、48、52、57、61、63、65、68、81）：逢此数者主事业顺遂、财运亨通、家庭和谐。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "数理吉凶", "keyword": "凶数", "content": "凶数（4、9、10、14、19、20、22、26、28、34、36、40、44、46、54、55、59、60、62、66、71）：逢此数者多波折，需后天努力弥补，或搭配其他格位吉数加以化解。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "数理吉凶", "keyword": "16画", "content": "人格16画（厚重）：性格宽容，品德高尚，善于领导，人际关系好，贵人多助，事业多有成就。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "数理吉凶", "keyword": "21画", "content": "人格21画（明月中天）：头脑聪明，独立自主，意志坚强，适合独当一面，中年后运势大旺。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "数理吉凶", "keyword": "23画", "content": "人格23画（壮盛昌隆）：才华出众，魄力十足，积极进取，有旺盛的生命力和创造力，财名双收。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "数理吉凶", "keyword": "24画", "content": "人格24画（光辉照人）：思维敏锐，理财能力强，财运极佳，家庭幸福，是财富积累的吉数之一。", "source": "姓名学五格剖象法"},
    # 三才配置
    {"module": "name_wuge", "category": "三才配置", "keyword": "木木木", "content": "天地人三才均为木：气势旺盛，进取心强，但易固执，缺乏变通。宜搭配金水调和，方能成大器。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "三才配置", "keyword": "水木火", "content": "水木火三才相生：运势顺畅，事业上升，财运旺盛，为三才配置中的吉格之一。人际关系融洽。", "source": "姓名学五格剖象法"},
    {"module": "name_wuge", "category": "三才配置", "keyword": "金水木", "content": "金水木三才相生：头脑清晰，执行力与灵活性兼备，事业发展稳健，晚年运势尤佳。", "source": "姓名学五格剖象法"},

    # ─────────────────────── 塔罗 tarot ───────────────────────
    # 大阿卡纳
    {"module": "tarot", "category": "大阿卡纳", "keyword": "愚者", "content": "愚者（0号）：新旅程的开始，充满可能性。正位：纯真、自由、冒险精神、新机遇。逆位：鲁莽冲动、缺乏计划、逃避现实。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "魔法师", "content": "魔法师（1号）：意志与能力的显现。正位：主动、技能、意志力、资源充足。逆位：操控、技能不足、机会错失。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "女祭司", "content": "女祭司（2号）：直觉与内在智慧。正位：直觉敏锐、内省、神秘知识、潜意识信息。逆位：压制直觉、信息隐藏、内心混乱。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "皇后", "content": "皇后（3号）：丰盛与孕育。正位：丰收、创造力、母性、自然之力、感官享受。逆位：依赖、创造力受阻、忽视自我照顾。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "皇帝", "content": "皇帝（4号）：权威与结构。正位：领导力、稳定、纪律、父性保护。逆位：独裁、缺乏弹性、权威滥用。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "教皇", "content": "教皇（5号）：传统与精神引导。正位：精神信仰、传统、导师、遵从规则。逆位：挑战教条、个人信仰、非传统选择。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "恋人", "content": "恋人（6号）：选择与联结。正位：爱情、价值观一致、重要选择、和谐关系。逆位：价值观分歧、选择困难、关系不和谐。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "战车", "content": "战车（7号）：意志力与胜利。正位：决心、控制、胜利、克服障碍。逆位：缺乏方向、失控、侵略性过强。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "力量", "content": "力量（8号）：内在力量与勇气。正位：勇气、耐心、内在力量、温柔的控制。逆位：软弱、自我怀疑、缺乏信心。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "隐士", "content": "隐士（9号）：独处与内省。正位：灵魂探索、独处、内在智慧、寻找真理。逆位：孤立、过度孤独、逃避社会。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "命运之轮", "content": "命运之轮（10号）：命运与转变。正位：命运转折、好运临门、周期循环、关键时机。逆位：坏运气、抗拒变化、命运不利。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "正义", "content": "正义（11号）：公平与真相。正位：公正、因果、客观分析、法律事务顺利。逆位：不公正、逃避责任、偏见。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "倒吊人", "content": "倒吊人（12号）：暂停与牺牲。正位：放下、等待、从新角度看问题、牺牲换取成长。逆位：拖延、抗拒改变、无谓的牺牲。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "死神", "content": "死神（13号）：转化与结束。正位：结束旧阶段、转化、不可避免的变化、重生。逆位：抗拒改变、停滞、无法放下过去。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "节制", "content": "节制（14号）：平衡与调和。正位：中庸之道、耐心、调和对立面、找到平衡。逆位：失衡、过度、缺乏长期视角。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "恶魔", "content": "恶魔（15号）：束缚与阴暗面。正位：束缚、物质执着、阴暗欲望、依附关系。逆位：从束缚中解放、面对阴暗面、重获自由。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "塔", "content": "塔（16号）：突然的崩塌与启示。正位：突然变化、崩溃、启示、推翻旧有秩序。逆位：逃避崩溃、延迟必要的改变。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "星星", "content": "星星（17号）：希望与灵感。正位：希望、灵感、内心平静、信念与信任。逆位：绝望、失去信念、幻灭。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "月亮", "content": "月亮（18号）：幻象与潜意识。正位：幻象、恐惧、直觉、潜意识信息需要解读。逆位：幻象消散、真相大白、释放恐惧。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "太阳", "content": "太阳（19号）：喜悦与成功。正位：成功、喜悦、活力、自信、乐观。逆位：过度乐观、暂时性的挫折、需要更多自我反思。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "审判", "content": "审判（20号）：觉醒与召唤。正位：觉醒、重生、内心召唤、重要决定。逆位：自我怀疑、压制内心召唤、无法释怀过去。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "大阿卡纳", "keyword": "世界", "content": "世界（21号）：完成与整合。正位：完成、整合、成就感、新循环开始。逆位：未完成、停滞、缺乏结局。", "source": "塔罗完全手册"},
    # 牌阵含义
    {"module": "tarot", "category": "牌阵", "keyword": "单张牌阵", "content": "单张牌阵：聚焦于当下最重要的能量或需要关注的信息，适合每日指引或简单问题。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "牌阵", "keyword": "三张牌阵", "content": "三张牌阵：过去-现在-未来，或情况-行动-结果。全面呈现事件的发展脉络，适合多数问题。", "source": "塔罗完全手册"},
    {"module": "tarot", "category": "牌阵", "keyword": "凯尔特十字", "content": "凯尔特十字（10张）：最经典的综合牌阵，覆盖当前状况、障碍、过去基础、近期未来、自我认知、外部影响、希望与恐惧、最终结果等多个维度。适合深度解读。", "source": "塔罗完全手册"},

    # ─────────────────────── 观音灵签 lot_guanyin ───────────────────────
    {"module": "lot_guanyin", "category": "签诗解析", "keyword": "上上签", "content": "上上签：诸事大吉，心想事成。感情顺遂，事业腾达，健康平安。宜把握时机，积极行动，善缘自聚。", "source": "观音灵签全文"},
    {"module": "lot_guanyin", "category": "签诗解析", "keyword": "上签", "content": "上签：吉中带顺，事情进展顺利但需努力配合。宜积极进取，贵人相助，目标可达。", "source": "观音灵签全文"},
    {"module": "lot_guanyin", "category": "签诗解析", "keyword": "中签", "content": "中签：平稳之兆，当前形势不偏不倚。需保持耐心，静待时机，切勿急躁冒进，循序渐进方能成事。", "source": "观音灵签全文"},
    {"module": "lot_guanyin", "category": "签诗解析", "keyword": "下签", "content": "下签：逆境之兆，当前不宜轻举妄动。宜反思自省，化解阻碍，调整心态后再出发。逆境是成长的催化剂。", "source": "观音灵签全文"},
    {"module": "lot_guanyin", "category": "签诗解析", "keyword": "下下签", "content": "下下签：诸事不顺，暗礁重重。宜低调行事，广积善缘，诚心祈祷，待时机转变。越挫越勇，逆境方显英雄本色。", "source": "观音灵签全文"},
    # 第1签
    {"module": "lot_guanyin", "category": "签文", "keyword": "第1签", "content": "第一签（上上签）：韩信将兵。签诗：大将兵权在掌中，南征北讨建奇功。凯歌已奏班师日，名显诸侯朝帝京。\n解意：此签大吉，如韩信领兵，才能得以施展，大事可成，功名显赫，宜把握时机，勇往直前。", "source": "观音灵签全文"},
    {"module": "lot_guanyin", "category": "签文", "keyword": "第2签", "content": "第二签（上签）：尧帝求贤。签诗：尧帝访贤下江南，有贤不用枉徒然。寻得贤人辅朝政，万民和悦享太平。\n解意：此签主贵人相助，遇到明智的伙伴或贵人，合作共赢，事业顺遂。", "source": "观音灵签全文"},
    {"module": "lot_guanyin", "category": "签文", "keyword": "第3签", "content": "第三签（中签）：东坡解围。签诗：眼前骤雨晚来晴，阴阳消长理分明。若是守得云开后，万里长空月更明。\n解意：暂时遭遇困境，但守得云开见月明，坚持等待后形势自然好转，勿急于求成。", "source": "观音灵签全文"},
    # 第4~10签（节选关键）
    {"module": "lot_guanyin", "category": "签文", "keyword": "第4签", "content": "第四签（上上签）：二龙戏珠。万般如意称心怀，百事亨通福自来。运势旺盛步步高，龙凤呈祥庆有余。\n解意：吉祥如意，运势极旺，财运、事业、感情均有佳兆，宜积极作为。", "source": "观音灵签全文"},
    {"module": "lot_guanyin", "category": "签文", "keyword": "第5签", "content": "第五签（中签）：姜太公钓鱼。时来运转自有期，守得枯木也逢春。静中自有动中乐，待时而动莫心急。\n解意：当前时机未到，宜静待时机，心平气和，机会自然来临。", "source": "观音灵签全文"},

    # ─────────────────────── 月老灵签 lot_yuelao ───────────────────────
    {"module": "lot_yuelao", "category": "签诗解析", "keyword": "上上签", "content": "上上签：姻缘天定，有情人终成眷属。感情顺遂，双方心意相通，宜主动表白或推进关系，吉祥如意。", "source": "月老灵签全文"},
    {"module": "lot_yuelao", "category": "签诗解析", "keyword": "上签", "content": "上签：缘分渐深，感情有进展。需要耐心经营，双方互相理解，真诚以待，感情将会稳定发展。", "source": "月老灵签全文"},
    {"module": "lot_yuelao", "category": "签诗解析", "keyword": "中签", "content": "中签：姻缘平稳，感情不冷不热。需要双方主动沟通，增进了解，缘分需要用心维系。", "source": "月老灵签全文"},
    {"module": "lot_yuelao", "category": "签诗解析", "keyword": "下签", "content": "下签：姻缘有阻，感情遭遇考验。宜放平心态，反思自身，化解误会，给彼此一些空间和时间。", "source": "月老灵签全文"},
    # 月老签文节选
    {"module": "lot_yuelao", "category": "签文", "keyword": "第1签", "content": "第一签（上上签）：有情人终成眷属。签诗：鸾凤呈祥好姻缘，月老牵线系红丝。两情相悦天作合，此生携手到白头。\n解意：此签大吉，姻缘美满，感情顺遂，是月老指引的好姻缘之兆。", "source": "月老灵签全文"},
    {"module": "lot_yuelao", "category": "签文", "keyword": "第2签", "content": "第二签（上签）：牛郎织女会鹊桥。签诗：相思情意比天长，虽有阻隔终相聚。鹊桥相会情更深，缘分牵引自来时。\n解意：感情虽有小阻，但最终有缘再聚，宜耐心等待，感情终会有好结果。", "source": "月老灵签全文"},
    {"module": "lot_yuelao", "category": "签文", "keyword": "第3签", "content": "第三签（中签）：守候花开时。签诗：春花未开莫心急，等待时机自然来。用心灌溉情意深，花开结果自有期。\n解意：感情处于等待期，宜静心等候，用真诚和行动去维系，缘分到了自然水到渠成。", "source": "月老灵签全文"},

    # ─────────────────────── 通用灵签 lot_generic ───────────────────────
    {"module": "lot_generic", "category": "签文", "keyword": "第1签", "content": "第一签（上签）：开门见喜。签诗：云散月明人自安，春风得意好扬鞭。若能稳住心中念，眼前道路自宽宽。\n解意：整体向好，事情已经开始松动，适合在稳住节奏后主动推进。", "source": "内置整理"},
    {"module": "lot_generic", "category": "签文", "keyword": "第2签", "content": "第二签（中签）：守成待机。签诗：舟行浅水莫争先，暂借东风再举帆。眼下若能多一步忍，来时方见好机缘。\n解意：目前更适合观察与准备，急着突破反而容易失手。", "source": "内置整理"},
    {"module": "lot_generic", "category": "签文", "keyword": "第3签", "content": "第三签（下签）：回头整顿。签诗：乱线难成锦上花，且将旧局慢慢查。若教根脚先厘正，后路方能稳到家。\n解意：先别急着追结果，当前更需要回头整理问题根源。", "source": "内置整理"},
    {"module": "lot_generic", "category": "签文", "keyword": "第4签", "content": "第四签（上上签）：贵人扶路。签诗：行至中途逢指引，迷津一渡见晴空。若能顺势承人力，此番谋望有成功。\n解意：近期容易遇到关键帮助，合作和请教比单打独斗更有效。", "source": "内置整理"},

    # ─────────────────────── 通用吉凶 common ───────────────────────
    {"module": "common", "category": "吉凶总论", "keyword": "大吉", "content": "大吉：诸事顺遂，天时地利人和，宜主动出击，积极把握机遇，功成名就指日可待。", "source": "易经总纲"},
    {"module": "common", "category": "吉凶总论", "keyword": "小吉", "content": "小吉：整体向好，但仍有小阻，需耐心推进，循序渐进，贵人适时相助，目标可期。", "source": "易经总纲"},
    {"module": "common", "category": "吉凶总论", "keyword": "中平", "content": "中平：当前局势平稳，既无大凶也无大吉。宜保持稳健，积累势能，等待突破时机。", "source": "易经总纲"},
    {"module": "common", "category": "吉凶总论", "keyword": "小凶", "content": "小凶：有阻碍但可化解。宜谨慎行事，避免冒险，广结善缘，以柔克刚，化阻力为动力。", "source": "易经总纲"},
    {"module": "common", "category": "吉凶总论", "keyword": "大凶", "content": "大凶：时机不利，宜守不宜攻。深度反思，调整方向，积蓄能量，待时机转变再行动。越挫越勇，方显本色。", "source": "易经总纲"},
]
